def transform(grid):
    # Extend a two-cell-high foreground vertical edge into the empty area to its right.
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    colors=set(x for row in g for x in row)
    fg=next((x for x in colors if x!=bg), bg)
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==fg and g[r+1][c]==fg and g[r][c+1]==bg and g[r+1][c+1]==bg:
                k=c+1
                while k<w and g[r][k]==bg and g[r+1][k]==bg:
                    g[r][k]=g[r+1][k]=1
                    k+=1
    return g
